#endif

const ll Mod = 1e9 + 7;
// const ll Mod = 998244353;
const ll MAXN = 1e6;

void solve(){
    ll x,y,n;cin>>x>>y>>n;
    ll a,b;
    ld val=1ll<<60;
    for(ll i=1;i<=n;i++){
        if(val>min((i*x)%y,y-(i*x)%y)*1.0/i){
            val=min((i*x)%y,y-(i*x)%y)*1.0/i;
            b=i;
            a=((i*x)%y<=y-(i*x)%y)?i*x/y:i*x/y+1;
        }
    }
    cout<<a<<"/"<<b<<"\n";
}

